def link_existing_suppliers(apps, schema_editor):
    """One supplier record per existing supplier account (accounts sharing a code share the record)."""
    User, Supplier = apps.get_model('portal', 'User'), apps.get_model('portal', 'Supplier')
    for u in User.objects.filter(role='supplier').order_by('id'):
        code = (u.code or f'S-{u.pk}').strip()
        sup = Supplier.objects.filter(code__iexact=code).first() or Supplier.objects.create(
            name=u.org or u.name, code=code, tax_no=u.tax_no or '', is_active=u.is_active)
        User.objects.filter(pk=u.pk).update(supplier=sup, code=sup.code)


